package com.anthony6996.hardcorecompass;
import com.anthony6996.hardcorecompass.command.CompassCommand;import com.anthony6996.hardcorecompass.config.ConfigManager;import com.anthony6996.hardcorecompass.listener.*;import com.anthony6996.hardcorecompass.manager.*;import com.anthony6996.hardcorecompass.storage.PlayerData;import org.bukkit.plugin.java.JavaPlugin;
public final class HardcoreCompassPlugin extends JavaPlugin{private LivesManager lives;private CompassManager compasses;private PlayerData data;private ConfigManager config;@Override public void onEnable(){saveDefaultConfig();config=new ConfigManager(this);data=new PlayerData(this);lives=new LivesManager(config,data);compasses=new CompassManager(this,config);compasses.registerRecipe();getServer().getPluginManager().registerEvents(new PlayerJoinListener(lives,compasses,config),this);getServer().getPluginManager().registerEvents(new LodestoneListener(compasses,config),this);getServer().getPluginManager().registerEvents(new CompassCraftListener(compasses),this);TeleportManager teleport=new TeleportManager(this,config,data);getServer().getPluginManager().registerEvents(new PlayerDeathListener(lives,compasses,teleport,config),this);getServer().getPluginManager().registerEvents(new PlayerRespawnListener(config),this);CompassCommand command=new CompassCommand(this,lives,config,compasses);getCommand("hcompass").setExecutor(command);getCommand("hcompass").setTabCompleter(command);}@Override public void onDisable(){if(lives!=null)lives.save();}public PlayerData getPlayerData(){return data;}public void reloadPluginConfig(){config.reload();compasses.registerRecipe();}}
